macro_rules! deps {
    () => {
        Error!();
        Action!();
        Mapping!();
        Arguments!();
        Response!();
        Round!();
        Ref!();
    };
}

macro_rules! with_fetch {
    () => {
        deps!();
        # [cfg (feature = "fetch")] mod with_fetch { use crate :: fetch :: { self , negotiate , refmap } ; # [doc = " For use in [`fetch`](crate::fetch())."] pub struct NegotiateContext < 'a , 'b , 'c , Objects , Alternates , AlternatesOut , AlternatesErr , Find > where Objects : gix_object :: Find + gix_object :: FindHeader + gix_object :: Exists , Alternates : FnOnce () -> Result < AlternatesOut , AlternatesErr > , AlternatesErr : Into < Box < dyn std :: error :: Error + Send + Sync + 'static > > , AlternatesOut : Iterator < Item = (gix_ref :: file :: Store , Find) > , Find : gix_object :: Find , { # [doc = " Access to the object database."] # [doc = " *Note* that the `exists()` calls must not trigger a refresh of the ODB packs as plenty of them might fail, i.e. find on object."] pub objects : & 'a Objects , # [doc = " Access to the git references database."] pub refs : & 'a gix_ref :: file :: Store , # [doc = " A function that returns an iterator over `(refs, objects)` for each alternate repository, to assure all known objects are added also according to their tips."] pub alternates : Alternates , # [doc = " The implementation that performs the negotiation later, i.e. prepare wants and haves."] pub negotiator : & 'a mut dyn gix_negotiate :: Negotiator , # [doc = " The commit-graph for use by the `negotiator` - we populate it with tips to initialize the graph traversal."] pub graph : & 'a mut gix_negotiate :: Graph < 'b , 'c > , } # [doc = " A trait to encapsulate steps to negotiate the contents of the pack."] # [doc = ""] # [doc = " Typical implementations use the utilities found in the [`negotiate`] module."] pub trait Negotiate { # [doc = " Typically invokes [`negotiate::mark_complete_and_common_ref()`]."] fn mark_complete_and_common_ref (& mut self) -> Result < negotiate :: Action , negotiate :: Error > ; # [doc = " Typically invokes [`negotiate::add_wants()`]."] # [doc = " Returns `true` if wants were added, or `false` if the negotiation should be aborted."] # [must_use] fn add_wants (& mut self , arguments : & mut fetch :: Arguments , remote_ref_target_known : & [bool]) -> bool ; # [doc = " Typically invokes [`negotiate::one_round()`]."] fn one_round (& mut self , state : & mut negotiate :: one_round :: State , arguments : & mut fetch :: Arguments , previous_response : Option < & fetch :: Response > ,) -> Result < (negotiate :: Round , bool) , negotiate :: Error > ; } # [doc = " The outcome of [`fetch()`](crate::fetch())."] # [derive (Debug , Clone)] pub struct Outcome { # [doc = " The most recent server response."] # [doc = ""] # [doc = " Useful to obtain information about new shallow boundaries."] pub last_response : fetch :: Response , # [doc = " Information about the negotiation to receive the new pack."] pub negotiate : NegotiateOutcome , } # [doc = " The negotiation-specific outcome of [`fetch()`](crate::fetch())."] # [derive (Debug , Clone)] pub struct NegotiateOutcome { # [doc = " The outcome of the negotiation stage of the fetch operation."] # [doc = ""] # [doc = " If it is…"] # [doc = ""] # [doc = " * [`negotiate::Action::MustNegotiate`] there will always be a `pack`."] # [doc = " * [`negotiate::Action::SkipToRefUpdate`] there is no `pack` but references can be updated right away."] # [doc = ""] # [doc = " Note that this is never [negotiate::Action::NoChange`] as this would mean there is no negotiation information at all"] # [doc = " so this structure wouldn't be present."] pub action : negotiate :: Action , # [doc = " Additional information for each round of negotiation."] pub rounds : Vec < negotiate :: Round > , } # [doc = " Information about the relationship between our refspecs, and remote references with their local counterparts."] # [doc = ""] # [doc = " It's the first stage that offers connection to the server, and is typically required to perform one or more fetch operations."] # [derive (Default , Debug , Clone)] pub struct RefMap { # [doc = " A mapping between a remote reference and a local tracking branch."] pub mappings : Vec < refmap :: Mapping > , # [doc = " The explicit refspecs that were supposed to be used for fetching."] # [doc = ""] # [doc = " Typically, they are configured by the remote and are referred to by"] # [doc = " [`refmap::SpecIndex::ExplicitInRemote`] in [`refmap::Mapping`]."] pub refspecs : Vec < gix_refspec :: RefSpec > , # [doc = " Refspecs which have been added implicitly due to settings of the `remote`, usually pre-initialized from"] # [doc = " [`extra_refspecs` in RefMap options](refmap::init::Context)."] # [doc = " They are referred to by [`refmap::SpecIndex::Implicit`] in [`refmap::Mapping`]."] # [doc = ""] # [doc = " They are never persisted nor are they typically presented to the user."] pub extra_refspecs : Vec < gix_refspec :: RefSpec > , # [doc = " Information about the fixes applied to the `mapping` due to validation and sanitization."] pub fixes : Vec < gix_refspec :: match_group :: validate :: Fix > , # [doc = " All refs advertised by the remote."] pub remote_refs : Vec < crate :: handshake :: Ref > , # [doc = " The kind of hash used for all data sent by the server, if understood by this client implementation."] # [doc = ""] # [doc = " It was extracted from the `handshake` as advertised by the server."] pub object_hash : gix_hash :: Kind , } }
    };
}

with_fetch!();